"use client";

import { useRef, useState, type ReactNode, type RefObject } from "react";
import { ArrowUp, Loader2, Trash2 } from "@workpal/ui/icons";
import { createShortcutChord } from "@workpal/core/shortcuts";
import { Button } from "@workpal/ui/components/ui/button";
import { IconButton } from "@workpal/ui/components/common/icon-button";
import { MAX_REPLY_ANNOTATIONS, type ReplyAnnotation } from "@workpal/core/drafts/reply-annotation";
import { ContentEditor, type ContentEditorRef } from "../../editor";
import { EditorOverlayOwnerContext } from "../../editor/overlay-owner";
import { ShortcutKeycaps } from "../../common/shortcut-keycaps";
import { useT } from "../../i18n";
import {
  useComposerVoice,
  VoiceErrorRow,
  VoiceHud,
  VoiceMicButton,
  VoiceSetupDialog,
  VoiceStrip,
} from "../../voice";

/** The existing reply/comment composer owns routing, uploads and submission. */
export interface AnnotationSendControls {
  submit: () => Promise<void>;
  submitting: boolean;
  uploading: boolean;
  targetMissing?: boolean;
  restart: boolean;
  recipients: ReactNode;
  draftContent: string;
  annotations: readonly ReplyAnnotation[];
}

export interface AnnotationComposerSlot {
  pending: ReplyAnnotation;
  render: (controls?: AnnotationSendControls) => ReactNode;
}

export function annotationsWithPending(annotations: readonly ReplyAnnotation[], pending?: ReplyAnnotation): readonly ReplyAnnotation[] {
  if (!pending) return annotations;
  const saved = annotations.some((a) => a.id === pending.id);
  return saved ? annotations.map((a) => a.id === pending.id ? pending : a) : [...annotations, pending];
}

const ENTER = createShortcutChord("Enter");
const SEND = createShortcutChord("Enter", { primary: true });

export function AnnotationComposer({
  issueId, owner, annotation, existing, number, editorRef, controls,
  sourceMissing, sourceChanged, canSave, onChange, onSave, onRemove, onBusyChange,
}: {
  issueId?: string;
  owner: string;
  annotation: ReplyAnnotation;
  existing: boolean;
  number: number;
  editorRef: RefObject<ContentEditorRef | null>;
  controls?: AnnotationSendControls;
  sourceMissing: boolean;
  sourceChanged: boolean;
  canSave: boolean;
  onChange: (note: string) => void;
  onSave: (note: string, close: boolean) => boolean;
  onRemove?: () => void;
  onBusyChange: (busy: boolean) => void;
}) {
  const { t } = useT("issues");
  const [initialNote] = useState(annotation.note);
  const [sending, setSending] = useState(false);
  const inFlight = useRef(false);
  const busy = sending || controls?.submitting === true;
  const otherAnnotations = controls?.annotations.filter((a) => a.id !== annotation.id).length ?? 0;
  const hasBody = !!controls?.draftContent.trim();
  const sendAll = otherAnnotations > 0 || hasBody;
  const sendDisabled = !annotation.note.trim() || !canSave || busy || !!controls?.uploading || !!controls?.targetMissing;
  const save = () => {
    if (busy || inFlight.current || !canSave) return;
    const note = editorRef.current?.getMarkdown() ?? "";
    if (note.trim()) onSave(note, true);
  };
  const send = async () => {
    if (!controls || controls.targetMissing || busy || inFlight.current || !canSave) return;
    const note = editorRef.current?.getMarkdown() ?? "";
    if (!note.trim()) return;
    inFlight.current = true;
    onBusyChange(true);
    setSending(true);
    try {
      // Commit first: the existing composer's failure/retry path owns the note.
      if (onSave(note, false)) await controls.submit();
    } finally {
      inFlight.current = false;
      onBusyChange(false);
      setSending(false);
    }
  };
  // No voice send: Enter saves the note here, so dictation only inserts.
  const voice = useComposerVoice({
    insert: (text) => editorRef.current?.insertText(text) ?? false,
    scope: annotation.id,
    disabled: busy,
  });

  return <EditorOverlayOwnerContext.Provider value={owner}>
    <div ref={voice.rootRef} onFocusCapture={voice.onFocusCapture}
      className="relative flex w-96 max-w-[calc(100vw-26px)] flex-col gap-1" aria-busy={busy || undefined}>
      <div className={busy ? "pointer-events-none opacity-60" : undefined} inert={busy || undefined}>
        <ContentEditor ref={editorRef} defaultValue={initialNote}
          ariaLabel={t(($) => $.reply.annotations.note_label)}
          placeholder={t(($) => $.reply.annotations.note_placeholder)}
          className="min-h-8 max-h-32 overflow-y-auto px-2 py-1.5"
          currentIssueId={issueId} showBubbleMenu={false} debounceMs={100}
          onUpdate={onChange} onEnter={save} onSubmit={send} />
      </div>
      <VoiceHud voice={voice} />
      <VoiceSetupDialog voice={voice} />
      <VoiceErrorRow voice={voice} className="mx-1" />
      {(sourceMissing || sourceChanged) && <p role={sourceMissing ? "alert" : undefined} className="px-2 text-caption text-muted-foreground">
        {t(($) => $.reply.annotations.source_changed)}
      </p>}
      {controls?.targetMissing && <p role="alert" className="px-2 text-caption text-destructive">
        {t(($) => $.reply.annotations.target_deleted)}
      </p>}
      {!canSave && <p className="px-2 text-caption text-muted-foreground">{t(($) => $.reply.annotations.count_limit, { count: MAX_REPLY_ANNOTATIONS })}</p>}
      {sendAll && <p className="px-2 text-caption text-muted-foreground">
        {otherAnnotations ? t(($) => hasBody ? $.reply.annotations.send_with_annotations_and_body : $.reply.annotations.send_with_annotations, { count: otherAnnotations })
          : t(($) => $.reply.annotations.send_with_body)}
      </p>}
      {voice.showStrip ? <div className="flex items-center gap-1 px-1 pb-1">
        {controls?.recipients && <div className="min-w-0 max-w-[60%] shrink-0 overflow-hidden">{controls.recipients}</div>}
        <VoiceStrip voice={voice} />
      </div> : <div className="flex flex-wrap items-center gap-1 px-1 pb-1" inert={busy || undefined}>
        {existing && onRemove && <IconButton variant="ghost" size="icon-sm"
          className="text-muted-foreground hover:text-destructive" label={t(($) => $.reply.annotations.remove, { number })}
          disabled={busy} onClick={onRemove}><Trash2 /></IconButton>}
        <div className="min-w-0 flex-1">{controls?.recipients}</div>
        <div className="ml-auto flex items-center gap-1">
          <VoiceMicButton voice={voice} />
          {controls && (controls.restart
            // Stopping a run must stay spelled out, never an unlabeled icon.
            ? <Button size="sm" variant="destructive" disabled={sendDisabled} onClick={send} aria-busy={busy || undefined}>
              {busy && <Loader2 className="animate-spin" />}
              {t(($) => $.comment.restart_send)}
              <ShortcutKeycaps shortcut={SEND} decorative />
            </Button>
            : <IconButton label={t(($) => sendAll ? $.reply.annotations.send_all : $.comment.send_tooltip)}
              shortcut={<ShortcutKeycaps shortcut={SEND} decorative />}
              disabled={sendDisabled} onClick={send} aria-busy={busy || undefined}>
              {busy ? <Loader2 className="animate-spin" /> : <ArrowUp />}
            </IconButton>)}
          <Button size="sm" disabled={!annotation.note.trim() || !canSave || busy} onClick={save}
            aria-label={t(($) => existing ? $.reply.annotations.save : $.reply.annotations.confirm_add)}>
            {t(($) => existing ? $.reply.annotations.save_short : $.reply.annotations.confirm_add_short)}
            <ShortcutKeycaps shortcut={ENTER} decorative />
          </Button>
        </div>
      </div>}
    </div>
  </EditorOverlayOwnerContext.Provider>;
}

"use client";

import { useRef, useState, useEffect, useMemo } from "react";
import { cn } from "@workpal/ui/lib/utils";
import { ContentEditor, type ContentEditorRef, useFileDropZone, FileDropOverlay, useLazyEditor, useUploadGate, useComposerSubmit } from "../../editor";
import { SubmitButton } from "@workpal/ui/components/common/submit-button";
import { Button } from "@workpal/ui/components/ui/button";
import { contentReferencesAttachment, type AgentTask } from "@workpal/core/types";
import { useShortcut } from "@workpal/core/shortcuts";
import { ShortcutKeycaps } from "../../common/shortcut-keycaps";
import { useCommentDraftStore } from "@workpal/core/issues/stores";
import { composeAnnotatedReply, hasReplyIntent } from "@workpal/core/drafts/reply-annotation";
import { annotationsWithPending, type AnnotationComposerSlot } from "./annotation-composer";
import { ReplyAnnotations } from "./reply-annotations";
import { useT } from "../../i18n";
import {
  useComposerVoice,
  VoiceErrorRow,
  VoiceHud,
  VoiceSetupDialog,
} from "../../voice";
import { CommentTriggerChips } from "./comment-trigger-chips";
import {
  ComposerToolbar,
  ComposerTools,
  QUIET_SEND_CLASS,
  useComposerFocus,
} from "./composer-frame";
import { commentTriggerPreviewSignature, useCommentTriggerPreview } from "../hooks/use-comment-trigger-preview";
import { useRecipientActions } from "../hooks/use-recipient-actions";
import { SteerAttachmentNotice } from "./steer-attachment-notice";
import { useStopRunsBeforeSend } from "./use-stop-runs-before-send";
import { useCommentUploads } from "./use-comment-uploads";
import { useQuickActionMenu } from "../hooks/use-quick-action-menu";
import { useStickyComposer } from "../hooks/use-sticky-composer";

interface CommentInputProps {
  issueId: string;
  /** Resolves true on success, false on failure. The composer keeps the text
   *  (editor locked + button spinning) until this settles, then clears only on
   *  success — a failed send must not silently discard the user's draft. */
  onSubmit: (content: string, attachmentIds?: string[], suppressAgentIds?: string[], steerTaskIds?: string[]) => Promise<string | boolean>;
  /** Called after the server accepts the comment and the composer is cleared. */
  onAccepted?: (commentId: string) => void;
  onEditAnnotation?: (id: string) => boolean;
  annotationComposer?: AnnotationComposerSlot;
}

// A top-level comment belongs to no thread, so it takes a running turn by
// default only when that turn has no thread of its own (an assignment run).
function steerTopLevelByDefault(task: AgentTask): boolean {
  return !task.trigger_comment_id;
}

function CommentInput({ issueId, onSubmit, onAccepted, onEditAnnotation, annotationComposer }: CommentInputProps) {
  const { t } = useT("issues");
  const { t: tEditor } = useT("editor");
  const sendShortcut = useShortcut("send");
  const editorRef = useRef<ContentEditorRef>(null);
  // Sending mid-upload would strip the pending image's blob URL out of the
  // markdown and bind no attachment id — the comment posts without the file.
  const uploadGate = useUploadGate(editorRef);
  // Subscribe to the persisted draft so text written into it from outside
  // this composer shows up even while it is mounted.
  // Quick actions in the `/` menu: picking one inserts the cached
  // body so the user can edit before sending, instead of firing immediately.
  const quickActionMenu = useQuickActionMenu();
  const draftKey = `new:${issueId}` as const;
  const [initialDraft] = useState(() =>
    useCommentDraftStore.getState().getDraft(draftKey),
  );
  const persistedDraft = useCommentDraftStore((store) => store.getDraft(draftKey));
  const [content, setContent] = useState(initialDraft ?? "");
  const [isEmpty, setIsEmpty] = useState(() => !initialDraft?.trim());
  const annotations = useCommentDraftStore((s) => s.getAnnotations(draftKey));
  const previewAnnotations = useMemo(() => annotationsWithPending(annotations, annotationComposer?.pending), [annotations, annotationComposer?.pending]);
  const composedContent = useMemo(() => composeAnnotatedReply(content, previewAnnotations), [content, previewAnnotations]);
  const canSend = annotations.length ? hasReplyIntent(content, annotations) : !isEmpty;
  const triggerPreview = useCommentTriggerPreview({ issueId, content: canSend || annotationComposer?.pending.note.trim() ? composedContent : "" });
  // Uploads for this composer session (MUL-5181). Owned by the module-level
  // coordinator and persisted in the draft store, so closing/scrolling the
  // composer away no longer drops an in-flight upload — its result lands in the
  // draft. `attachments` (completed rows) drives both the submit `attachment_ids`
  // payload and the editor's AttachmentDownloadProvider; `uploads` drives the
  // status chips (uploading / failed / interrupted).
  // `gate` widens the editor gate with coordinator-owned placeholders, so a
  // composer reopened over a still-in-flight upload cannot send past it.
  const { attachments: pendingAttachments, handleUpload, gate } =
    useCommentUploads(draftKey, { issueId }, uploadGate, editorRef);
  const hasAttachments = useMemo(
    () => pendingAttachments.some((a) => contentReferencesAttachment(content, a)) || gate.uploading,
    [pendingAttachments, content, gate.uploading],
  );
  const { recipients, attachmentsBlockSteer, routing, setAction, reset: resetRecipients } = useRecipientActions({
    issueId,
    agents: triggerPreview.agents,
    allowSteer: true,
    hasAttachments,
    steerByDefault: steerTopLevelByDefault,
    resetKey: issueId,
  });
  const stopRunsBeforeSend = useStopRunsBeforeSend(issueId);

  // Readonly-first: the composer renders as a same-looking static shell until
  // the user shows intent (click / keyboard / file drop). An unsent draft is
  // standing intent — mount the real editor immediately so the draft is
  // visible and editable, exactly like the pre-lazy behavior.
  const lazy = useLazyEditor({
    initialActive:
      !!initialDraft?.trim() ||
      useCommentDraftStore.getState().getUploads(draftKey).length > 0,
    editorRef,
  });
  const { isDragOver, dropZoneProps } = useFileDropZone({
    onDrop: lazy.uploadOrQueue,
  });
  // Sticky preference (Settings → Preferences): issue-detail pins this
  // composer to the bottom of the scroll viewport when enabled. Shared with
  // the host so the height cap below can never outlive the pinning.
  const sticky = useStickyComposer();

  // Draft persistence. Hydrate from store on mount via `defaultValue` above
  // (ContentEditorRef has no setContent, so this is the only injection point).
  // Flush on every onUpdate (debounced upstream) + visibilitychange/pagehide
  // so tab close / mobile background doesn't lose work. Cleared on submit.
  const setDraft = useCommentDraftStore((s) => s.setDraft);
  useEffect(() => {
    // Only an actual stored value is an external update. An absent entry is
    // not a command to erase the editor: it is normal during the synchronous
    // keystroke -> store handoff and after explicit submit cleanup.
    if (persistedDraft === undefined) return;
    const next = persistedDraft;
    if (next === content) return;
    setContent(next);
    setIsEmpty(!next.trim());
    if (next.trim()) lazy.activate();
  }, [content, lazy, persistedDraft]);
  useEffect(() => {
    const flush = () => {
      const md = editorRef.current?.getMarkdown();
      if (md && md.trim().length > 0) setDraft(draftKey, md);
    };
    const onVis = () => { if (document.visibilityState === "hidden") flush(); };
    document.addEventListener("visibilitychange", onVis);
    window.addEventListener("pagehide", flush);
    return () => {
      document.removeEventListener("visibilitychange", onVis);
      window.removeEventListener("pagehide", flush);
    };
  }, [draftKey, setDraft]);

  // Await-then-render send (MUL-5181): the shared hook reads the markdown,
  // guards empty/in-flight, re-checks the upload gate, locks + spins via
  // `submitting`, and clears only once the server accepts — a failed send keeps
  // the draft instead of silently dropping it.
  // Stale-submit guard (MUL-5181 P0): if this composer unmounts mid-submit
  // (issue detail closed) and the user reopens and types a new draft under the
  // same key, the late success may only clear the draft it submitted.
  const mountedRef = useRef(true);
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);
  const submittedEntryRef = useRef<unknown>(null);
  // Set by `onAccepted` only on the branch that actually wiped the editor; read
  // back by `afterAccepted`. Bound this way because the stale-submit guard can
  // leave a mid-flight draft in place: dropping the caret then would yank it
  // out of the sentence the user is still typing.
  const editorScrubbedRef = useRef(false);
  const acceptedCommentIdRef = useRef<string | null>(null);

  const { submitting, submit } = useComposerSubmit({
    editorRef,
    uploadGate: gate,
    normalize: (raw) => {
      const current = useCommentDraftStore.getState().getAnnotations(draftKey);
      return hasReplyIntent(raw, current) ? composeAnnotatedReply(raw, current) : "";
    },
    // A top-level comment ends a turn: the caret is dropped rather than kept,
    // so the composer stops reading as "still writing" once the comment is
    // posted above it. Thread replies do the same — see ReplyInput.
    afterAccepted: () => (editorScrubbedRef.current ? "blur" : "none"),
    onSubmit: async (content) => {
      editorScrubbedRef.current = false;
      const { suppressAgentIds, steerTaskIds } = routing;
      // A preview still catching up with an edited @mention can name a
      // recipient this comment no longer addresses: never stop a run on it.
      const previewMatches = triggerPreview.isCurrent && commentTriggerPreviewSignature(content) === commentTriggerPreviewSignature(composedContent);
      const restartTaskIds = previewMatches ? routing.restartTaskIds : [];
      if (!(await stopRunsBeforeSend(restartTaskIds))) return false;
      // Flush the editor's pending debounce before snapshotting — a late flush
      // of pre-submit typing must not read as an edit made during the request.
      const pending = editorRef.current?.flushPendingUpdate?.();
      if (pending != null) setDraft(draftKey, pending);
      submittedEntryRef.current = useCommentDraftStore.getState().drafts[draftKey];
      // Bind only uploads the BODY still references (MUL-5181): deleting an
      // inline image really unbinds it. Uploads that finished after a close
      // are written back into the body by the settle handler, so surviving
      // files are referenced too — never silently attached.
      const activeIds = pendingAttachments
        .filter((a) => contentReferencesAttachment(content, a))
        .map((a) => a.id);
      return onSubmit(
        content,
        activeIds.length > 0 ? activeIds : undefined,
        suppressAgentIds.length > 0 ? suppressAgentIds : undefined,
        steerTaskIds.length > 0 ? steerTaskIds : undefined,
      ).then((commentId) => {
        acceptedCommentIdRef.current = typeof commentId === "string" ? commentId : null;
        return !!commentId;
      });
    },
    onAccepted: () => {
      // Success may only consume the entry it submitted (MUL-5181 P0): edits
      // made while the request was in flight — or by a reopened composer after
      // this one unmounted — survive both in the store and in the editor.
      // Flush the pending debounce first so typing still inside the window is
      // judged correctly (a no-op flush preserves entry identity).
      const lateMd = editorRef.current?.flushPendingUpdate?.();
      if (lateMd != null) setDraft(draftKey, lateMd);
      const store = useCommentDraftStore.getState();
      const live = store.drafts[draftKey];
      const untouched = live === undefined || live === submittedEntryRef.current;
      if (untouched) store.clearDraft(draftKey);
      if (!mountedRef.current || !untouched) return;
      editorRef.current?.clearContent();
      setContent("");
      setIsEmpty(true);
      resetRecipients();
      editorScrubbedRef.current = true;
      if (acceptedCommentIdRef.current) onAccepted?.(acceptedCommentIdRef.current);
    },
  });

  const voice = useComposerVoice({
    insert: (text) => editorRef.current?.insertText(text) ?? false,
    // Sending while a run would be restarted stays an explicit click on the
    // destructive button.
    submit: routing.restartTaskIds.length === 0 ? () => void submit() : undefined,
    activate: () => lazy.activate(),
    scope: issueId,
  });
  const { focused, focusProps } = useComposerFocus();
  const showsTriggerChips = recipients.length > 0 || triggerPreview.blocked.length > 0 || triggerPreview.hasAllMembersMention;

  return (<>
    {annotationComposer?.render({
      submit, submitting, uploading: gate.uploading, restart: routing.restartTaskIds.length > 0,
      draftContent: content, annotations,
      recipients: <CommentTriggerChips recipients={recipients} blocked={triggerPreview.blocked}
        hasAllMembersMention={triggerPreview.hasAllMembersMention} draftContent={composedContent} onActionChange={setAction} />,
    })}
    <div
      data-mc="comment-composer"
      {...dropZoneProps}
      {...focusProps}
      className={cn(
        "relative flex flex-col rounded-lg bg-card ring-1 transition-shadow",
        focused ? "ring-foreground/25" : "ring-border",
      )}
      ref={voice.rootRef}
      onFocusCapture={voice.onFocusCapture}
    >
      {attachmentsBlockSteer && <div className="px-3 pt-2">
        <SteerAttachmentNotice />
      </div>}
      {annotations.length > 0 && <div className="px-3 pt-2">
        <ReplyAnnotations draftKey={draftKey} annotations={annotations} disabled={submitting}
          onEditAnnotation={onEditAnnotation} />
      </div>}
      {/* Lock the editor while the send is in flight. ContentEditor can't
          toggle Tiptap's `editable` post-mount (see its docstring), so the
          documented way to make it non-interactive is a pointer-events-none +
          dimmed wrapper. */}
      {lazy.active && (
      <div
        className={cn(
          "flex-1 min-h-0 overflow-y-auto px-3 py-2",
          // Pinned to the viewport bottom the composer grows upward; cap it
          // so a long draft can't swallow the whole timeline (the editor
          // area scrolls internally instead).
          sticky && "max-h-[40vh]",
          submitting && "pointer-events-none opacity-60",
          !lazy.ready && "hidden",
        )}
        aria-busy={submitting || undefined}
      >
        <ContentEditor
          ref={editorRef}
          value={persistedDraft ?? content}
          onReady={lazy.onReady}
          placeholder={t(($) => $.comment.leave_comment_placeholder)}
          onUpdate={(md) => {
            setContent(md);
            setIsEmpty(!md.trim());
            // Debounced upstream (debounceMs=100). Persist on every tick so a
            // reload or scroll-out-of-viewport restores work to the keystroke.
            // setDraft keeps any pending attachments and drops the entry only
            // when text AND attachments are both empty.
            setDraft(draftKey, md);
          }}
          onSubmit={submit}
          onUploadFile={handleUpload}
          onUploadingChange={uploadGate.onUploadingChange}
          debounceMs={100}
          currentIssueId={issueId}
          attachments={pendingAttachments}
          enableSlashCommands
          slashCommandMode="command"
          quickActionMenu={quickActionMenu}
        />
      </div>
      )}
      {/* Static shell — visually clones the empty single-line composer.
          Real editor mounts (hidden) on first intent; shell stays visible
          until it's ready so the card never blanks or shifts. */}
      {!lazy.ready && (
        <div
          data-testid="comment-composer-shell"
          role="button"
          tabIndex={0}
          aria-label={t(($) => $.comment.leave_comment_placeholder)}
          className="flex-1 min-h-0 cursor-text px-3 py-2"
          onClick={() => lazy.activate()}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              lazy.activate();
            }
          }}
        >
          {/* rich-text-editor + <p>: the shell line inherits the editor's
              exact type metrics (line-height 1.625 from prose.css), so the
              shell→editor swap doesn't shift layout. */}
          <div className="rich-text-editor text-body">
            <p className="text-muted-foreground">{t(($) => $.comment.leave_comment_placeholder)}</p>
          </div>
        </div>
      )}
      <VoiceHud voice={voice} />
      <VoiceSetupDialog voice={voice} />
      <VoiceErrorRow voice={voice} className="mx-2 mb-1" />
      <ComposerToolbar
        className="px-1.5 pb-1"
        voice={voice}
        hasRecipients={showsTriggerChips}
        recipients={<CommentTriggerChips
          recipients={recipients}
          blocked={triggerPreview.blocked}
          hasAllMembersMention={triggerPreview.hasAllMembersMention}
          draftContent={composedContent}
          onActionChange={setAction}
        />}
        tools={<ComposerTools voice={voice} onAttach={(file) => lazy.uploadOrQueue([file])} />}
        send={routing.restartTaskIds.length > 0 ? (
          <Button
            size="sm"
            variant="destructive"
            // eslint-disable-next-line no-restricted-syntax -- composer send button, the one round button
            className="rounded-full px-3"
            onClick={submit}
            disabled={!canSend || submitting || gate.uploading}
          >
            {t(($) => $.comment.restart_send)}
          </Button>
        ) : <SubmitButton
          className={QUIET_SEND_CLASS}
          onClick={submit}
          disabled={!canSend}
          loading={submitting}
          busy={gate.uploading}
          disabledReason={gate.uploading
            ? tEditor(($) => $.upload.in_progress)
            : !canSend && annotations.length > 0
              ? t(($) => $.reply.annotations.intent_hint)
              : undefined}
          tooltip={sendShortcut
            ? (
              <>
                {t(($) => $.comment.send_tooltip)}
                <ShortcutKeycaps shortcut={sendShortcut} decorative />
              </>
            )
            : t(($) => $.comment.send_tooltip)}
          ariaLabel={gate.uploading
            ? tEditor(($) => $.upload.in_progress)
            : t(($) => $.comment.send_tooltip)}
        />}
      />
      {isDragOver && <FileDropOverlay />}
    </div>
  </>);
}

export { CommentInput };

"use client";

import { composeAnnotatedReply, EMPTY_REPLY_ANNOTATIONS, hasReplyIntent } from "@workpal/core/drafts/reply-annotation";
import { annotationsWithPending, type AnnotationComposerSlot } from "./annotation-composer";
import { ReplyAnnotations } from "./reply-annotations";
import { useCallback, useRef, useState, useEffect, useImperativeHandle, useMemo, type Ref } from "react";
import { toast } from "sonner";
import { ContentEditor, type ContentEditorRef, useFileDropZone, FileDropOverlay, useLazyEditor, useUploadGate, useComposerSubmit } from "../../editor";
import { SubmitButton } from "@workpal/ui/components/common/submit-button";
import { Button } from "@workpal/ui/components/ui/button";
import { ActorAvatar } from "../../common/actor-avatar";
import { contentReferencesAttachment, type AgentTask } from "@workpal/core/types";
import { useShortcut } from "@workpal/core/shortcuts";
import { ShortcutKeycaps } from "../../common/shortcut-keycaps";
import { useCommentDraftStore, type CommentDraftKey } from "@workpal/core/issues/stores";
import { cn } from "@workpal/ui/lib/utils";
import type { AvatarSize } from "@workpal/ui/lib/avatar-size";
import { useT } from "../../i18n";
import {
  useComposerVoice,
  VoiceErrorRow,
  VoiceHud,
  VoiceSetupDialog,
} from "../../voice";
import { CommentTriggerChips } from "./comment-trigger-chips";
import {
  ComposerIdleTools,
  ComposerToolbar,
  ComposerTools,
  QUIET_SEND_CLASS,
  useComposerExpanded,
  useComposerFocus,
} from "./composer-frame";
import { commentTriggerPreviewSignature, useCommentTriggerPreview } from "../hooks/use-comment-trigger-preview";
import { useRecipientActions } from "../hooks/use-recipient-actions";
import { SteerAttachmentNotice } from "./steer-attachment-notice";
import { useStopRunsBeforeSend } from "./use-stop-runs-before-send";
import { useCommentUploads } from "./use-comment-uploads";
import { useQuickActionMenu } from "../hooks/use-quick-action-menu";

// Types

/** Lets the thread around the box move the caret into it, e.g. from a menu. */
interface ReplyInputHandle {
  focus: () => void;
}

interface ReplyInputProps {
  handleRef?: Ref<ReplyInputHandle>;
  issueId: string;
  parentId: string;
  placeholder?: string;
  avatarType: string;
  avatarId: string;
  /** Resolves true on success, false on failure — the reply box keeps its text
   *  (locked + spinning) until then, clearing only on success. */
  onSubmit: (content: string, attachmentIds?: string[], suppressAgentIds?: string[], steerTaskIds?: string[]) => Promise<string | boolean>;
  /** Called after the server accepts the reply and the composer is cleared. */
  onAccepted?: (commentId: string) => void;
  size?: "sm" | "default";
  /** When set, hydrates/persists the in-progress reply via the draft store.
   *  Required for replies inside virtualized timeline threads, where the
   *  enclosing CommentCard may unmount on scroll-out. */
  draftKey?: CommentDraftKey;
  targetMissing?: boolean;
  onEditAnnotation?: (id: string) => boolean;
  annotationComposer?: AnnotationComposerSlot;
  /** Whether a running turn takes this reply by default: true for the turn
   *  that belongs to this thread. Other recipients' turns can still be chosen. */
  steerByDefault?: (task: AgentTask) => boolean;
}

const NEVER_STEER_BY_DEFAULT = () => false;

// ReplyInput

function ReplyInput({
  handleRef,
  issueId,
  parentId,
  placeholder,
  avatarType,
  avatarId,
  onSubmit,
  onAccepted,
  size = "default",
  draftKey,
  onEditAnnotation,
  annotationComposer,
  targetMissing = false,
  steerByDefault = NEVER_STEER_BY_DEFAULT,
}: ReplyInputProps) {
  const { t } = useT("issues");
  const { t: tEditor } = useT("editor");
  const sendShortcut = useShortcut("send");
  const placeholderText = placeholder ?? t(($) => $.reply.placeholder);
  const editorRef = useRef<ContentEditorRef>(null);
  const composerRef = useRef<HTMLDivElement>(null);
  // See CommentInput — replying mid-upload posts without the file.
  const uploadGate = useUploadGate(editorRef);
  // Quick actions in the `/` menu — same catalog and same insert-don't-run
  // behavior as the top-level composer. A reply posts to the same issue, so
  // `/` has to offer the same thing here (MUL-5588).
  const quickActionMenu = useQuickActionMenu();
  // If a draft key is provided, hydrate from store on mount (defaultValue is
  // the only injection point on ContentEditorRef) and flush on every onUpdate.
  const [initialDraft] = useState(() =>
    draftKey ? useCommentDraftStore.getState().getDraft(draftKey) : undefined,
  );
  const [content, setContent] = useState(initialDraft ?? "");
  const setDraft = useCommentDraftStore((s) => s.setDraft);
  const [isEmpty, setIsEmpty] = useState(!initialDraft?.trim());
  const annotations = useCommentDraftStore((s) => draftKey ? s.getAnnotations(draftKey) : EMPTY_REPLY_ANNOTATIONS);
  const previewAnnotations = useMemo(() => annotationsWithPending(annotations, annotationComposer?.pending), [annotations, annotationComposer?.pending]);
  const composedContent = useMemo(() => composeAnnotatedReply(content, previewAnnotations), [content, previewAnnotations]);
  const canSend = !targetMissing && (annotations.length ? hasReplyIntent(content, annotations) : !isEmpty);
  // Saving the first pending annotation will fix the target before submission.
  const previewParentId = annotations.length === 0 ? annotationComposer?.pending.sourceCommentId ?? parentId : parentId;
  const triggerPreview = useCommentTriggerPreview({ issueId, parentId: previewParentId, content: !targetMissing && (canSend || annotationComposer?.pending.note.trim()) ? composedContent : "" });
  // Uploads for this reply session (MUL-5181) — owned by the coordinator. With
  // a draftKey they persist in the draft store so scroll-out/close no longer
  // drops an in-flight upload; without one (no persistence context) they fall
  // back to session-local state inside the hook.
  // `gate` widens the editor gate with coordinator-owned placeholders — see
  // CommentInput.
  const { uploads, attachments: pendingAttachments, handleUpload, removeUpload, gate } =
    useCommentUploads(draftKey, { issueId }, uploadGate, editorRef);
  const hasAttachments = useMemo(
    () => pendingAttachments.some((a) => contentReferencesAttachment(content, a)) || gate.uploading,
    [pendingAttachments, content, gate.uploading],
  );
  const { recipients, attachmentsBlockSteer, routing, setAction, reset: resetRecipients } = useRecipientActions({
    issueId,
    agents: triggerPreview.agents,
    allowSteer: true,
    hasAttachments,
    steerByDefault,
    resetKey: `${issueId}:${previewParentId}`,
  });
  const stopRunsBeforeSend = useStopRunsBeforeSend(issueId);
  // A pending annotation note previews recipients while the reply itself is
  // still empty, so the chip row can render under the one-line placeholder.
  const showsTriggerChips = recipients.length > 0 || triggerPreview.blocked.length > 0 || triggerPreview.hasAllMembersMention;

  // Readonly-first: static shell until intent; an unsent draft mounts the
  // real editor immediately (see CommentInput). This is also what keeps the
  // reply box working across Virtuoso scroll-out — a typed draft rehydrates
  // into a live editor when the card remounts, an untouched box folds back
  // to the shell.
  const lazy = useLazyEditor({
    initialActive:
      !!initialDraft?.trim() ||
      (draftKey ? useCommentDraftStore.getState().getUploads(draftKey).length > 0 : false),
    editorRef,
  });
  useImperativeHandle(handleRef, () => ({ focus: () => lazy.activate() }), [lazy]);
  const { isDragOver, dropZoneProps } = useFileDropZone({
    onDrop: lazy.uploadOrQueue,
  });

  // Flush on tab close / mobile background — same rationale as CommentInput.
  useEffect(() => {
    if (!draftKey) return;
    const flush = () => {
      const md = editorRef.current?.getMarkdown();
      if (md && md.trim().length > 0) setDraft(draftKey, md);
    };
    const onVis = () => { if (document.visibilityState === "hidden") flush(); };
    document.addEventListener("visibilitychange", onVis);
    window.addEventListener("pagehide", flush);
    return () => {
      document.removeEventListener("visibilitychange", onVis);
      window.removeEventListener("pagehide", flush);
    };
  }, [draftKey, setDraft]);

  // Await-then-render send (see CommentInput): the shared hook keeps the text,
  // locks + spins, and clears only once the server accepts it.
  // Stale-submit guard — see CommentInput.
  const mountedRef = useRef(true);
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);
  const submittedEntryRef = useRef<unknown>(null);
  // See CommentInput: bound to the branch that actually wiped the editor, so a
  // draft the stale-submit guard kept is never disturbed.
  const editorScrubbedRef = useRef(false);
  const acceptedCommentIdRef = useRef<string | null>(null);

  const { submitting, submit } = useComposerSubmit({
    editorRef,
    uploadGate: gate,
    normalize: (raw) => {
      const current = draftKey ? useCommentDraftStore.getState().getAnnotations(draftKey) : EMPTY_REPLY_ANNOTATIONS;
      return !targetMissing && hasReplyIntent(raw, current) ? composeAnnotatedReply(raw, current) : "";
    },
    // Drop the caret once the reply is posted, same as a top-level comment: a
    // focused editor swallows the page's keyboard shortcuts, so keeping it here
    // would trap the user until they click away. Bound to `editorScrubbedRef`
    // so a draft the stale-submit guard kept stays focused.
    afterAccepted: () => (editorScrubbedRef.current ? "blur" : "none"),
    onSubmit: async (content) => {
      editorScrubbedRef.current = false;
      const currentParentId = (draftKey ? useCommentDraftStore.getState().drafts[draftKey]?.replyTarget?.commentId : undefined) ?? parentId;
      if (currentParentId !== previewParentId) {
        toast.error(t(($) => $.reply.recipients_changed));
        return false;
      }
      const { suppressAgentIds, steerTaskIds } = routing;
      // A preview still catching up with an edited @mention can name a
      // recipient this comment no longer addresses: never stop a run on it.
      const previewMatches = triggerPreview.isCurrent && commentTriggerPreviewSignature(content) === commentTriggerPreviewSignature(composedContent);
      const restartTaskIds = previewMatches ? routing.restartTaskIds : [];
      if (!(await stopRunsBeforeSend(restartTaskIds))) return false;
      if (draftKey) {
        // Flush pending debounce before snapshotting — see CommentInput.
        const pending = editorRef.current?.flushPendingUpdate?.();
        if (pending != null) setDraft(draftKey, pending);
        submittedEntryRef.current = useCommentDraftStore.getState().drafts[draftKey];
      }
      // Bind only uploads the body still references (see CommentInput):
      // deleting an inline image really unbinds it; close-surviving uploads
      // are written back into the body by the settle handler.
      const activeIds = pendingAttachments
        .filter((a) => contentReferencesAttachment(content, a))
        .map((a) => a.id);
      return onSubmit(
        content,
        activeIds.length > 0 ? activeIds : undefined,
        suppressAgentIds.length > 0 ? suppressAgentIds : undefined,
        steerTaskIds.length > 0 ? steerTaskIds : undefined,
      ).then((commentId) => {
        acceptedCommentIdRef.current = typeof commentId === "string" ? commentId : null;
        return !!commentId;
      });
    },
    onAccepted: () => {
      // Success may only consume the entry it submitted — see CommentInput.
      if (draftKey) {
        const lateMd = editorRef.current?.flushPendingUpdate?.();
        if (lateMd != null) setDraft(draftKey, lateMd);
        const store = useCommentDraftStore.getState();
        const live = store.drafts[draftKey];
        const untouched = live === undefined || live === submittedEntryRef.current;
        if (untouched) store.clearDraft(draftKey);
        if (!mountedRef.current || !untouched) return;
      } else {
        if (!mountedRef.current) return;
        uploads.forEach((u) => removeUpload(u.clientUploadId));
      }
      editorRef.current?.clearContent();
      setContent("");
      setIsEmpty(true);
      resetRecipients();
      editorScrubbedRef.current = true;
      if (acceptedCommentIdRef.current) onAccepted?.(acceptedCommentIdRef.current);
    },
  });

  const avatarSize: AvatarSize = size === "sm" ? "sm" : "md";
  const voice = useComposerVoice({
    insert: (text) => editorRef.current?.insertText(text) ?? false,
    // A send that would restart a run stays an explicit click — see CommentInput.
    submit: routing.restartTaskIds.length === 0 ? () => void submit() : undefined,
    activate: () => lazy.activate(),
    scope: `${issueId}:${parentId}`,
  });
  const { focused, focusProps } = useComposerFocus();
  // One line at rest, like the comment box — see CommentInput.
  const expanded = useComposerExpanded(
    focused || !isEmpty || annotations.length > 0 || showsTriggerChips || voice.showStrip || submitting || gate.uploading,
    voice,
  );
  const voiceRootRef = voice.rootRef;
  const bindComposer = useCallback((element: HTMLDivElement | null) => {
    composerRef.current = element;
    voiceRootRef(element);
  }, [voiceRootRef]);

  return (<>
    {annotationComposer?.render({
      submit, submitting, uploading: gate.uploading, targetMissing, restart: routing.restartTaskIds.length > 0,
      draftContent: content, annotations,
      recipients: <CommentTriggerChips recipients={recipients} blocked={triggerPreview.blocked}
        hasAllMembersMention={triggerPreview.hasAllMembersMention} draftContent={composedContent} onActionChange={setAction} />,
    })}
    <div className="group/editor flex items-start gap-2.5">
      <ActorAvatar
        actorType={avatarType}
        actorId={avatarId}
        size={avatarSize}
        className="mt-0.5 shrink-0"
      />
      <div
        {...dropZoneProps}
        {...focusProps}
        ref={bindComposer}
        className="relative flex min-w-0 flex-1 flex-col"
        onFocusCapture={voice.onFocusCapture}
      >
        {attachmentsBlockSteer && <SteerAttachmentNotice />}
        {draftKey && annotations.length > 0 && <>
          {targetMissing && <p role="alert" className="mb-2 text-caption text-destructive">{t(($) => $.reply.annotations.target_deleted)}</p>}
          <ReplyAnnotations draftKey={draftKey} annotations={annotations}
            disabled={submitting} onEditAnnotation={onEditAnnotation} />
        </>}
        <div className="flex min-h-0 flex-1 items-center">
        {/* Lock the editor while the reply is in flight — see CommentInput. */}
        {lazy.active && (
        <div
          className={cn(
            "min-w-0 flex-1 min-h-0 overflow-y-auto",
            submitting && "pointer-events-none opacity-60",
            !lazy.ready && "hidden",
          )}
          aria-busy={submitting || undefined}
        >
          <ContentEditor
            ref={editorRef}
            defaultValue={initialDraft}
            onReady={lazy.onReady}
            placeholder={placeholderText}
            onUpdate={(md) => {
              setContent(md);
              setIsEmpty(!md.trim());
              // setDraft keeps any pending attachments and drops the entry only
              // when text AND attachments are both empty.
              if (draftKey) setDraft(draftKey, md);
            }}
            onSubmit={submit}
            onUploadFile={handleUpload}
            onUploadingChange={uploadGate.onUploadingChange}
            debounceMs={100}
            currentIssueId={issueId}
            attachments={pendingAttachments}
            enableSlashCommands
            slashCommandMode="command"
            quickActionMenu={quickActionMenu}
          />
        </div>
        )}
        {/* Static shell — clones the empty single-line reply box (see
            CommentInput for the pattern). */}
        {!lazy.ready && (
          <div
            data-testid="reply-composer-shell"
            role="button"
            tabIndex={0}
            aria-label={placeholderText}
            className="min-w-0 flex-1 cursor-text rich-text-editor text-body"
            onClick={() => lazy.activate()}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                lazy.activate();
              }
            }}
          >
            {/* <p> under rich-text-editor: same type metrics as the real
                editor's empty paragraph — no height jump on swap. */}
            <p className="text-muted-foreground">{placeholderText}</p>
          </div>
        )}
        {!expanded && <ComposerIdleTools className="-my-1" voice={voice} onAttach={(file) => lazy.uploadOrQueue([file])} />}
        </div>
        <VoiceHud voice={voice} />
        <VoiceSetupDialog voice={voice} />
        <VoiceErrorRow voice={voice} className="mt-1" />
        {expanded && <ComposerToolbar
          className="mt-1 animate-in fade-in slide-in-from-top-1 duration-150"
          voice={voice}
          hasRecipients={showsTriggerChips}
          recipients={<CommentTriggerChips
            recipients={recipients}
            blocked={triggerPreview.blocked}
            hasAllMembersMention={triggerPreview.hasAllMembersMention}
            draftContent={composedContent}
            onActionChange={setAction}
          />}
          tools={<ComposerTools voice={voice} onAttach={(file) => lazy.uploadOrQueue([file])} />}
          send={routing.restartTaskIds.length > 0 ? (
            <Button
              size="sm"
              variant="destructive"
              // eslint-disable-next-line no-restricted-syntax -- composer send button, the one round button
              className="rounded-full px-3"
              onClick={submit}
              disabled={!canSend || submitting || gate.uploading}
            >
              {t(($) => $.comment.restart_send)}
            </Button>
          ) : <SubmitButton
            className={QUIET_SEND_CLASS}
            onClick={submit}
            disabled={!canSend}
            loading={submitting}
            busy={gate.uploading}
            disabledReason={gate.uploading
              ? tEditor(($) => $.upload.in_progress)
              : !canSend && annotations.length > 0 && !targetMissing
                ? t(($) => $.reply.annotations.intent_hint)
                : undefined}
            tooltip={sendShortcut
              ? (
                <>
                  {t(($) => $.comment.send_tooltip)}
                  <ShortcutKeycaps shortcut={sendShortcut} decorative />
                </>
              )
              : t(($) => $.comment.send_tooltip)}
            ariaLabel={gate.uploading
              ? tEditor(($) => $.upload.in_progress)
              : t(($) => $.comment.send_tooltip)}
          />}
        />}
        {isDragOver && <FileDropOverlay />}
      </div>
    </div>
  </>);
}

export { ReplyInput, type ReplyInputHandle, type ReplyInputProps };

"use client";

import { useState, type FocusEvent, type MouseEvent, type ReactNode } from "react";
import { FileUploadButton } from "@workpal/ui/components/common/file-upload-button";
import { cn } from "@workpal/ui/lib/utils";
import { VoiceMicButton, VoiceStrip, type ComposerVoice } from "../../voice";

/**
 * Shared by the issue comment box and thread replies: one line with attach
 * and mic at rest, a toolbar row with recipients and send once focused or
 * written in.
 */

/** Send stays a light tint until there is something to send. */
export const QUIET_SEND_CLASS =
  "disabled:opacity-100 disabled:bg-muted disabled:text-faint-foreground aria-disabled:opacity-100 aria-disabled:bg-muted aria-disabled:text-faint-foreground";

const IDLE_TOOLS = "data-composer-idle-tools";

/**
 * Whether focus is inside the box. Focus on the resting attach and mic does
 * not count: expanding would unmount the button before its click lands.
 */
export function useComposerFocus() {
  const [focused, setFocused] = useState(false);
  return {
    focused,
    focusProps: {
      onFocus: (event: FocusEvent<HTMLElement>) => {
        if (!(event.target as HTMLElement).closest(`[${IDLE_TOOLS}]`)) setFocused(true);
      },
      onBlur: (event: FocusEvent<HTMLElement>) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setFocused(false);
      },
    },
  };
}

/**
 * Whether the box shows its toolbar. Frozen while the mic is held: dictation
 * focuses the editor, and the pressed mic must not unmount before release.
 */
export function useComposerExpanded(wanted: boolean, voice: ComposerVoice): boolean {
  const [settled, setSettled] = useState(wanted);
  if (!voice.holding && settled !== wanted) setSettled(wanted);
  return voice.holding ? settled : wanted;
}

/** Attach, then mic: the mic sits next to send, where its recording strip grows from. */
export function ComposerTools({ voice, onAttach }: { voice: ComposerVoice; onAttach: (file: File) => void }) {
  return (
    <>
      <FileUploadButton multiple onSelect={onAttach} />
      <VoiceMicButton voice={voice} />
    </>
  );
}

/** The tools at the end of the one-line box at rest. */
export function ComposerIdleTools({
  voice,
  onAttach,
  className,
}: {
  voice: ComposerVoice;
  onAttach: (file: File) => void;
  className?: string;
}) {
  return (
    <div {...{ [IDLE_TOOLS]: "" }} className={cn("flex shrink-0 items-center gap-1", className)}>
      <ComposerTools voice={voice} onAttach={onAttach} />
    </div>
  );
}

/** A click on the toolbar's empty space must not take focus out of the box and fold it. */
function keepFocus(event: MouseEvent<HTMLElement>) {
  if (!(event.target as HTMLElement).closest("button, a, input, [role='button']")) event.preventDefault();
}

/**
 * The expanded box's bottom row. Recipients keep their place on the left
 * while dictating; the strip takes the rest of the row instead of covering
 * them.
 */
export function ComposerToolbar({
  voice,
  recipients,
  hasRecipients,
  tools,
  send,
  className,
}: {
  voice: ComposerVoice;
  recipients: ReactNode;
  hasRecipients: boolean;
  tools: ReactNode;
  send: ReactNode;
  className?: string;
}) {
  return (
    <div
      className={cn("flex h-9 items-center gap-1", className)}
      onMouseDown={keepFocus}
    >
      {hasRecipients && (
        <div className={cn("min-w-0 overflow-hidden", voice.showStrip ? "max-w-[45%] shrink-0" : "flex-1")}>
          {recipients}
        </div>
      )}
      {voice.showStrip ? (
        <VoiceStrip voice={voice} />
      ) : (
        <>
          {!hasRecipients && <div className="flex-1" />}
          {tools}
          {send}
        </>
      )}
    </div>
  );
}

"use client";

/**
 * Comment-composer binding for the coordinated-upload engine (MUL-5181, L2).
 *
 * All upload mechanics — coordinator ownership, generation guards, the
 * confirmed write-back of a finished upload's link into the draft body, the
 * combined submit gate — live in `editor/use-coordinated-uploads`. This file
 * only maps the engine onto the comment draft store, keyed by
 * {@link CommentDraftKey}. Without a key (a reply box with no persistence
 * context) the engine falls back to component-local uploads that die with the
 * mount, matching pre-L2 behavior.
 */

import { useMemo, type RefObject } from "react";
import type { DraftUpload } from "@workpal/core/drafts";
import type { UploadContext } from "@workpal/core/hooks/use-file-upload";
import { useCommentDraftStore, type CommentDraftKey } from "@workpal/core/issues/stores";
import type { UploadGate } from "../../editor/use-upload-gate";
import type { ContentEditorRef } from "../../editor/content-editor";
import {
  useCoordinatedUploads,
  type CoordinatedUploads,
  type UploadDraftBinding,
} from "../../editor/use-coordinated-uploads";

const EMPTY_UPLOADS: DraftUpload[] = [];

export type CommentUploads = CoordinatedUploads;

export function useCommentUploads(
  draftKey: CommentDraftKey | undefined,
  ctx: UploadContext,
  editorGate: UploadGate,
  editorRef: RefObject<ContentEditorRef | null>,
): CommentUploads {
  const storeUploads = useCommentDraftStore((s) =>
    draftKey ? s.getUploads(draftKey) : EMPTY_UPLOADS,
  );

  // Referentially stable per key — settle closures capture it and must keep
  // working after this component unmounts, so every accessor goes through
  // getState().
  const binding = useMemo<UploadDraftBinding | undefined>(() => {
    if (!draftKey) return undefined;
    return {
      registryKey: `comment:${draftKey}`,
      getUploads: () => useCommentDraftStore.getState().getUploads(draftKey),
      addUpload: (u) => useCommentDraftStore.getState().addUpload(draftKey, u),
      settleUpload: (id, att) => useCommentDraftStore.getState().settleUpload(draftKey, id, att),
      failUpload: (id, err) => useCommentDraftStore.getState().failUpload(draftKey, id, err),
      removeUpload: (id) => useCommentDraftStore.getState().removeUpload(draftKey, id),
      getBody: () => useCommentDraftStore.getState().getDraft(draftKey) ?? "",
      appendToBody: (md) => useCommentDraftStore.getState().appendToDraftContent(draftKey, md),
    };
  }, [draftKey]);

  return useCoordinatedUploads(binding, storeUploads, ctx, editorGate, editorRef);
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { keepPreviousData, useQuery } from "@tanstack/react-query";
import { api } from "@workpal/core/api";
import { issueKeys } from "@workpal/core/issues/queries";
import { parseMentions } from "@workpal/core/issues/comment-trigger-outcomes";
import type { CommentTriggerPreviewAgent, CommentTriggerOutcome } from "@workpal/core/types";

const COMMENT_TRIGGER_PREVIEW_DEBOUNCE_MS = 300;
const NOTE_COMMAND_RE = /^\/note(?:$|\s)/i;

export interface UseCommentTriggerPreviewResult {
  agents: CommentTriggerPreviewAgent[];
  // Explicit @agent / @squad mentions that will NOT trigger if posted as-is
  // (MUL-4525 §2), so the composer can warn before sending.
  blocked: CommentTriggerOutcome[];
  // A structured @all mention is a member broadcast, but never starts agents
  // by itself. This is static mention semantics, not a delivery guarantee:
  // edits do not notify, and a new comment may have no eligible recipients.
  hasAllMembersMention: boolean;
  /**
   * Whether `agents` answers the draft's current mentions. While a changed
   * @mention is still debouncing or loading, the previous answer is shown;
   * nothing destructive may act on it.
   */
  isCurrent: boolean;
}

export function isNoteCommentDraft(content: string): boolean {
  return NOTE_COMMAND_RE.test(content.replace(/^[ \t\r\n]+/, ""));
}

export function commentTriggerPreviewSignature(content: string): string {
  if (!content.trim() || isNoteCommentDraft(content)) return "empty";

  const seen = new Set<string>();
  const tokens: string[] = [];
  for (const { type, id } of parseMentions(content)) {
    if (type === "issue") continue;
    const token = `${type}:${id}`;
    if (seen.has(token)) continue;
    seen.add(token);
    tokens.push(token);
  }

  return `nonempty|${tokens.join(",")}`;
}

function queryKeyMatchesPreviewContext(
  queryKey: readonly unknown[] | undefined,
  issueId: string,
  parentId: string,
  editingCommentId: string,
) {
  if (!queryKey) return false;
  const prefix = issueKeys.commentTriggerPreview(issueId);
  return (
    prefix.every((part, index) => queryKey[index] === part) &&
    queryKey[prefix.length] === parentId &&
    queryKey[prefix.length + 1] === editingCommentId
  );
}

function useDebouncedSignature(signature: string) {
  const [debouncedSignature, setDebouncedSignature] = useState("empty");

  useEffect(() => {
    if (signature === "empty") {
      setDebouncedSignature("empty");
      return;
    }

    const timer = window.setTimeout(() => {
      setDebouncedSignature(signature);
    }, COMMENT_TRIGGER_PREVIEW_DEBOUNCE_MS);

    return () => window.clearTimeout(timer);
  }, [signature]);

  return debouncedSignature;
}

export function useCommentTriggerPreview({
  issueId,
  parentId,
  editingCommentId,
  content,
}: {
  issueId: string;
  parentId?: string;
  editingCommentId?: string;
  content: string;
}): UseCommentTriggerPreviewResult {
  const signature = useMemo(() => commentTriggerPreviewSignature(content), [content]);
  const hasAllMembersMention = useMemo(
    () => parseMentions(content).some(({ type, id }) => type === "all" && id === "all"),
    [content],
  );
  const debouncedSignature = useDebouncedSignature(signature);
  const contentRef = useRef(content);
  const parentKey = parentId ?? "";
  const editingKey = editingCommentId ?? "";

  useEffect(() => {
    contentRef.current = content;
  }, [content]);

  const previewQuery = useQuery({
    queryKey: [...issueKeys.commentTriggerPreview(issueId), parentKey, editingKey, debouncedSignature],
    queryFn: () => api.previewCommentTriggers(issueId, contentRef.current, parentId, editingCommentId),
    enabled: signature !== "empty" && debouncedSignature !== "empty",
    retry: false,
    // The answer depends on live queue state (pending-task dedup), not just
    // the mention set, so a cached result must revalidate when its signature
    // reappears — Infinity here once pinned a stale "nobody triggers"
    // snapshot taken while the agent was still queued.
    staleTime: 0,
    // Keep the previous agent list only while the same composer context is
    // re-fetching. Crossing issue/parent/edit context must not display stale
    // chips from another composer.
    placeholderData: (previousData, previousQuery) =>
      queryKeyMatchesPreviewContext(previousQuery?.queryKey, issueId, parentKey, editingKey)
        ? keepPreviousData(previousData)
        : undefined,
  });

  // Loading and errors intentionally surface as "no agents": the preview is
  // an enhancement, and the composer renders nothing for an empty list.
  if (signature === "empty" || debouncedSignature === "empty") {
    return { agents: [], blocked: [], hasAllMembersMention, isCurrent: signature === "empty" };
  }

  return {
    agents: previewQuery.data?.agents ?? [],
    blocked: previewQuery.data?.blocked ?? [],
    hasAllMembersMention,
    isCurrent: signature === debouncedSignature && previewQuery.isSuccess && !previewQuery.isPlaceholderData,
  };
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { issueTasksOptions } from "@workpal/core/issues/queries";
import { useCommentComposerStore } from "@workpal/core/issues/stores";
import {
  agentRunState,
  recipientActions,
  recipientRouting,
  resolveRecipientAction,
  type AgentRunState,
  type RecipientAction,
  type RecipientRouting,
} from "@workpal/core/issues/run-steering";
import type { AgentTask, CommentTriggerPreviewAgent } from "@workpal/core/types";

const NO_TASKS: AgentTask[] = [];
const ACTIVE_STATUSES = new Set<AgentTask["status"]>(["queued", "deferred", "dispatched", "waiting_local_directory", "running"]);
const NO_CHOICES: Record<string, RecipientAction> = {};

export interface RecipientEntry {
  agent: CommentTriggerPreviewAgent;
  state: AgentRunState;
  action: RecipientAction;
  actions: RecipientAction[];
}

/**
 * The composer's per-recipient choice. The preview decides WHO receives the
 * message (existing trigger rules); each recipient's live run on this issue
 * decides what can happen to it: steer a running turn, fold into a queued
 * run, or start a new one.
 */
export function useRecipientActions({
  issueId,
  agents,
  allowSteer,
  hasAttachments = false,
  steerByDefault: steerHere,
  resetKey,
}: {
  issueId: string;
  agents: CommentTriggerPreviewAgent[];
  /** False for edits: an edit neither steers nor stops a run. */
  allowSteer: boolean;
  hasAttachments?: boolean;
  /** Whether a running turn takes the message by default from this composer. */
  steerByDefault: (task: AgentTask) => boolean;
  /** Choices reset when the composer's context changes. */
  resetKey: string;
}) {
  // Every comment row mounts this hook for its edit composer, so it reads only
  // the active runs of its own recipients: with none (the usual idle row) it
  // neither fetches nor re-renders on unrelated task events.
  const agentKey = agents.map((agent) => agent.id).join(",");
  const selectActive = useCallback((all: AgentTask[]) => {
    const ids = new Set(agentKey.split(","));
    return all.filter((task) => ids.has(task.agent_id) && ACTIVE_STATUSES.has(task.status));
  }, [agentKey]);
  const { data: tasks = NO_TASKS } = useQuery({
    ...issueTasksOptions(issueId),
    enabled: !!issueId && agents.length > 0,
    select: selectActive,
  });
  // The personal default can turn steering off for every composer; it only
  // decides what happens without a per-message choice.
  const steerWithoutChoice = useCommentComposerStore((s) => s.runningAgentReply !== "after_run");
  const steerByDefault = useCallback(
    (task: AgentTask) => steerWithoutChoice && steerHere(task),
    [steerWithoutChoice, steerHere],
  );
  const [chosen, setChosen] = useState<Record<string, RecipientAction>>(NO_CHOICES);

  useEffect(() => {
    setChosen(NO_CHOICES);
  }, [resetKey]);

  // Forget choices for agents that are no longer recipients (an @mention removed).
  useEffect(() => {
    const visible = new Set(agents.map((agent) => agent.id));
    setChosen((prev) => {
      const next = Object.fromEntries(Object.entries(prev).filter(([id]) => visible.has(id)));
      return Object.keys(next).length === Object.keys(prev).length ? prev : next;
    });
  }, [agents]);

  const recipients = useMemo<RecipientEntry[]>(() => agents.map((agent) => {
    const state = agentRunState(tasks, agent.id);
    const opts = {
      canSteer: allowSteer && !hasAttachments,
      canRestart: allowSteer,
      steerByDefault: state.kind === "running" && steerByDefault(state.task),
    };
    return {
      agent,
      state,
      action: resolveRecipientAction(state, chosen[agent.id], opts),
      actions: recipientActions(state, opts),
    };
  }), [agents, tasks, chosen, allowSteer, hasAttachments, steerByDefault]);

  // A recipient would take this in its running turn, but files cannot go there.
  const attachmentsBlockSteer = allowSteer && hasAttachments && recipients.some((r) =>
    r.state.kind === "running" && r.state.steerable
    && (chosen[r.agent.id] === "steer" || (!chosen[r.agent.id] && steerByDefault(r.state.task))));

  const setAction = useCallback((agentId: string, action: RecipientAction) => {
    setChosen((prev) => (prev[agentId] === action ? prev : { ...prev, [agentId]: action }));
  }, []);

  const reset = useCallback(() => {
    setChosen(NO_CHOICES);
  }, []);

  const routing = useMemo<RecipientRouting>(() => recipientRouting(recipients.map((r) => ({
    agentId: r.agent.id, action: r.action, state: r.state,
  }))), [recipients]);

  return { recipients, attachmentsBlockSteer, routing, setAction, reset };
}

"use client";

import { useCallback, useMemo } from "react";
import { toast } from "sonner";
import { useQuery } from "@tanstack/react-query";
import { useCurrentWorkspace } from "@workpal/core/paths";
import { buildQuickActionBody, quickActionListOptions } from "@workpal/core/quick-actions";
import { useT } from "../../i18n";

/**
 * Supplies the comment composer's `/` menu with this workspace's quick actions
 * (MUL-5465).
 *
 * Picking one INSERTS the cached body rather than running it — the composer
 * path exists precisely for the "this time is different" case, so the user
 * gets to edit and then send with the normal shortcut. Running without review
 * is what the sidebar button is for.
 *
 * The menu offers the same catalog the sidebar shows. Inserting draft text
 * needs no invocation preflight; the comment send path checks permission just
 * as it does for a hand-typed mention.
 *
 * Reads workspace identity through `useCurrentWorkspace` (nullable) rather
 * than `useWorkspaceId` (throws): the comment composer also mounts outside a
 * workspace route, and an enhancement like this must degrade to "no quick
 * actions in the menu", never take the composer down with it.
 */
export function useQuickActionMenu() {
  const { t } = useT("issues");
  const workspace = useCurrentWorkspace();
  const wsId = workspace?.id ?? "";
  const { data } = useQuery({
    ...quickActionListOptions(wsId),
    enabled: wsId !== "",
  });

  const actions = useMemo(
    () => (data ?? []).filter((a) => a.status === "active"),
    [data],
  );

  const getQuickActions = useCallback(
    () => actions.map((a) => ({ id: a.id, name: a.name, description: a.description || undefined })),
    [actions],
  );
  const getQuickActionContent = useCallback((quickActionId: string) => {
    const action = actions.find((a) => a.id === quickActionId);
    if (!action) return "";
    const content = buildQuickActionBody(action);
    if (content === null) {
      toast.error(t(($) => $.comment.trigger_blocked_target_unavailable));
      return "";
    }
    return content;
  }, [actions, t]);

  return useMemo(
    () => ({ getQuickActions, getQuickActionContent }),
    [getQuickActions, getQuickActionContent],
  );
}

