import { useIsMobile } from "@workpal/ui/hooks/use-mobile";
import { useCommentComposerStore } from "@workpal/core/issues/stores";

/**
 * Whether the bottom comment composer is pinned to the scroll viewport.
 *
 * The stored preference (Settings → Preferences) is the user's answer for a
 * screen with room to spare. A narrow viewport is not that screen:
 *
 *  - The chat launcher owns the bottom-right corner of every workspace page
 *    (see `--chat-launcher-clearance`). A pinned composer sits under it at
 *    every scroll position, and the part it covers is the send button.
 *  - Pinned, the composer costs ~15% of a phone viewport permanently, on a
 *    surface people mostly read rather than write on.
 *
 * Below `md` the composer therefore rides the end of the timeline, which is
 * where a phone reader scrolls to comment anyway. The preference is not
 * rewritten — it still applies the moment the viewport is wide enough.
 *
 * Both the composer and its host read this, so the pinning and the 40vh height
 * cap that only makes sense while pinned can never disagree.
 */
export function useStickyComposer(): boolean {
  const preferred = useCommentComposerStore((s) => s.sticky);
  const isMobile = useIsMobile();
  return preferred && !isMobile;
}

import type { AgentTask, CommentSupplementReceipt, TimelineEntry } from "../types";

/** The run-scoped capability that lets a running turn take additional input. */
export const TASK_SUPPLEMENT_CAPABILITY = "task-supplement-v1";

type ReceiptFields = Pick<
  TimelineEntry,
  "supplements" | "supplement_task_id" | "supplement_status" | "supplement_failure_reason" | "supplement_delivered_at"
>;

/**
 * Every running turn a comment steered. Servers that predate multi-run
 * steering send only the single supplement_* fields, without the agent.
 */
export function commentSupplementReceipts(entry: ReceiptFields): CommentSupplementReceipt[] {
  if (entry.supplements?.length) return entry.supplements;
  if (!entry.supplement_task_id || !entry.supplement_status) return [];
  return [{
    task_id: entry.supplement_task_id,
    status: entry.supplement_status,
    failure_reason: entry.supplement_failure_reason,
    delivered_at: entry.supplement_delivered_at,
  }];
}

/** A receipt whose turn has not received it yet. */
export function isSupplementInFlight(receipt: CommentSupplementReceipt): boolean {
  return receipt.status === "pending" || receipt.status === "delivering";
}

/**
 * What one recipient is doing on this issue right now, which decides how a
 * message to it can be handled: steer a running turn, fold into a queued run,
 * or start a new one.
 */
export type AgentRunState =
  | { kind: "idle" }
  | { kind: "queued"; task: AgentTask }
  | { kind: "starting"; task: AgentTask }
  | { kind: "running"; task: AgentTask; steerable: boolean };

/** Whether this member can add a message to the task's running turn. */
export function isSteerableTask(task: AgentTask): boolean {
  return task.status === "running"
    && task.supplement_capability === TASK_SUPPLEMENT_CAPABILITY
    && task.can_supplement === true;
}

export function agentRunState(tasks: readonly AgentTask[], agentId: string): AgentRunState {
  // A running turn wins over a queued follow-up: it is what a message reaches now.
  let queued: AgentTask | undefined;
  let starting: AgentTask | undefined;
  for (const task of tasks) {
    if (task.agent_id !== agentId) continue;
    if (task.status === "running") return { kind: "running", task, steerable: isSteerableTask(task) };
    if (task.status === "dispatched" || task.status === "waiting_local_directory") starting ??= task;
    else if (task.status === "queued" || task.status === "deferred") queued ??= task;
  }
  if (starting) return { kind: "starting", task: starting };
  if (queued) return { kind: "queued", task: queued };
  return { kind: "idle" };
}

/** How a message reaches one recipient. */
export type RecipientAction =
  /** Into the running turn, read at its next step. */
  | "steer"
  /** Normal trigger while the recipient is busy: handled once this turn ends. */
  | "after_run"
  /** Stop the current turn, then start over with this message. */
  | "restart"
  /** Normal trigger for an idle recipient, or one whose run is still queued. */
  | "start"
  /** Post without triggering this recipient. */
  | "skip";

export interface RecipientActionOptions {
  /** False while editing, or when the message carries files: a running turn takes text only. */
  canSteer: boolean;
  /** False while editing: an edit never stops a run. */
  canRestart: boolean;
  /** Steer by default. The composer sets this for the running turn's own thread. */
  steerByDefault: boolean;
}

export function recipientActions(state: AgentRunState, opts: RecipientActionOptions): RecipientAction[] {
  if (state.kind === "idle" || state.kind === "queued") return ["start", "skip"];
  const actions: RecipientAction[] = [];
  if (state.kind === "running" && state.steerable && opts.canSteer) actions.push("steer");
  actions.push("after_run");
  if (opts.canRestart) actions.push("restart");
  actions.push("skip");
  return actions;
}

/** The chosen action while it is still available, otherwise the default. */
export function resolveRecipientAction(
  state: AgentRunState,
  chosen: RecipientAction | undefined,
  opts: RecipientActionOptions,
): RecipientAction {
  const actions = recipientActions(state, opts);
  if (chosen && actions.includes(chosen)) return chosen;
  if (opts.steerByDefault && actions.includes("steer")) return "steer";
  return actions.find((action) => action !== "steer")!;
}

export interface RecipientRouting {
  suppressAgentIds: string[];
  /** The exact running turns chosen: a turn that ends first is never swapped for another. */
  steerTaskIds: string[];
  /** Turns to stop before the comment is posted, so it starts a fresh run. */
  restartTaskIds: string[];
}

export function recipientRouting(
  recipients: readonly { agentId: string; action: RecipientAction; state: AgentRunState }[],
): RecipientRouting {
  const routing: RecipientRouting = { suppressAgentIds: [], steerTaskIds: [], restartTaskIds: [] };
  for (const { agentId, action, state } of recipients) {
    if (action === "skip") routing.suppressAgentIds.push(agentId);
    else if (action === "steer" && state.kind === "running") routing.steerTaskIds.push(state.task.id);
    else if (action === "restart" && state.kind !== "idle") routing.restartTaskIds.push(state.task.id);
  }
  return routing;
}

import { queryOptions } from "@tanstack/react-query";
import { api } from "../api";

/**
 * Quick action catalog queries (MUL-5465).
 *
 * ONE projection, shared by settings and the issue sidebar. There used to be a
 * second "runnable only" projection that filtered by invoke permission; it was
 * removed because it made two people looking at the same issue see different
 * sidebars with no explanation. Permission is now answered once, at run time.
 */
export const quickActionKeys = {
  all: (wsId: string) => ["quick-actions", wsId] as const,
  list: (wsId: string, includeArchived = false) =>
    [...quickActionKeys.all(wsId), "list", includeArchived] as const,
};

export function quickActionListOptions(wsId: string, includeArchived = false) {
  return queryOptions({
    queryKey: quickActionKeys.list(wsId, includeArchived),
    queryFn: () => api.listQuickActions({ includeArchived }),
    select: (data) => data.quick_actions,
  });
}

import type { QuickAction } from "../types";

type QuickActionBody = Pick<
  QuickAction,
  "prompt" | "assignee_type" | "assignee_id" | "target_name" | "target_missing"
>;

/** Draft text only; the comment send path checks invocation permission. */
export function buildQuickActionBody(action: QuickActionBody): string | null {
  if (action.target_missing) return null;
  if (action.assignee_type === "") return action.prompt;
  if (
    (action.assignee_type !== "agent" && action.assignee_type !== "squad") ||
    !action.assignee_id ||
    !action.target_name
  ) return null;

  return `[@${action.target_name}](mention://${action.assignee_type}/${action.assignee_id})\n\n${action.prompt}`;
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768
// Tailwind `md`. Below it the nav is a sheet and list/detail surfaces fold to
// one column. From here up to `lg` the nav stays a docked column but starts
// collapsed (see SIDEBAR_AUTO_COLLAPSE_QUERY), which leaves a foldable's inner
// screen or a tablet enough reading width for both panes.
const COMPACT_BREAKPOINT = 768

function useIsBelow(breakpoint: number) {
  const [isBelow, setIsBelow] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${breakpoint - 1}px)`)
    const onChange = () => {
      setIsBelow(window.innerWidth < breakpoint)
    }
    mql.addEventListener("change", onChange)
    setIsBelow(window.innerWidth < breakpoint)
    return () => mql.removeEventListener("change", onChange)
  }, [breakpoint])

  return !!isBelow
}

export function useIsMobile() {
  return useIsBelow(MOBILE_BREAKPOINT)
}

export function useIsCompact() {
  return useIsBelow(COMPACT_BREAKPOINT)
}

import { create } from "zustand";
import { createJSONStorage, persist } from "zustand/middleware";
import { defaultStorage } from "../../platform/storage";

/**
 * What a reply does by default when it reaches a running agent that would
 * otherwise take it in its current turn: `steer` adds it to that turn,
 * `after_run` starts a new run once the current one ends. Either way the
 * composer's recipient chip can change it for a single message.
 */
export type RunningAgentReply = "steer" | "after_run";

/**
 * How images in the issue timeline's comments lay out: `thumbnails` keeps
 * them small (attached images in a row, body images height-capped) and opens
 * the full size in the viewer; `full` shows every image at its full size.
 */
export type CommentImageLayout = "thumbnails" | "full";

/**
 * Personal preferences for the issue-detail comment composer and timeline.
 *
 * `sticky` pins the bottom comment bar to the scroll viewport so it stays
 * reachable while reading a long timeline. `runningAgentReply` picks the
 * default for a reply to a running agent. `imageLayout` picks how comment
 * images lay out. All are personal habits (like theme), so they persist
 * globally via `defaultStorage` rather than per-workspace storage.
 */
interface CommentComposerStore {
  sticky: boolean;
  runningAgentReply: RunningAgentReply;
  imageLayout: CommentImageLayout;
  toggleSticky: () => void;
  setRunningAgentReply: (value: RunningAgentReply) => void;
  setImageLayout: (value: CommentImageLayout) => void;
}

export const useCommentComposerStore = create<CommentComposerStore>()(
  persist(
    (set) => ({
      sticky: true,
      runningAgentReply: "steer",
      imageLayout: "thumbnails",
      toggleSticky: () => set((s) => ({ sticky: !s.sticky })),
      setRunningAgentReply: (runningAgentReply) => set({ runningAgentReply }),
      setImageLayout: (imageLayout) => set({ imageLayout }),
    }),
    {
      name: "workpal_comment_composer",
      storage: createJSONStorage(() => defaultStorage),
    },
  ),
);

